// Golden Crust Bakery — shared opening-hours, menu, and pricing logic.

type Weekday = 'monday' | 'tuesday' | 'wednesday' | 'thursday' | 'friday' | 'saturday' | 'sunday';

type Category = 'Breads' | 'Pastries' | 'Cakes' | 'Drinks';

type DietaryTag = 'gluten' | 'dairy' | 'nuts' | 'egg' | 'vegan';

interface OpeningSpan {
  opens: string;
  closes: string;
}

interface DayHours {
  day: Weekday;
  spans: OpeningSpan[];
}

type OpeningHoursTable = DayHours[];

interface HolidayClosure {
  date: string;
  name: string;
}

interface OpeningStatus {
  open: boolean;
  label: string;
  day: Weekday;
  spans: OpeningSpan[];
}

interface WeeklyHoursRow {
  day: Weekday;
  label: string;
  spans: OpeningSpan[];
  closed: boolean;
}

interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  category: Category;
  tags: DietaryTag[];
  freshBake: boolean;
}

interface MenuFilters {
  category?: Category;
  tag?: DietaryTag;
  query?: string;
}

const WEEKDAYS: Weekday[] = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];

const DAY_LABELS: Record<Weekday, string> = {
  monday: 'Monday',
  tuesday: 'Tuesday',
  wednesday: 'Wednesday',
  thursday: 'Thursday',
  friday: 'Friday',
  saturday: 'Saturday',
  sunday: 'Sunday'
};

const CATEGORY_ORDER: Category[] = ['Breads', 'Pastries', 'Cakes', 'Drinks'];

/**
 * Convert an "HH:MM" 24-hour clock string into minutes past midnight.
 *
 * @param value - a clock string in "HH:MM" form
 * @returns minutes past midnight, or -1 when the input is malformed
 */
function clockToMinutes(value: string): number {
  if (typeof value !== 'string') {
    return -1;
  }
  const match = /^([0-9]{1,2}):([0-9]{2})$/.exec(value.trim());
  if (match === null) {
    return -1;
  }
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  if (hours < 0 || hours > 23 || minutes < 0 || minutes > 59) {
    return -1;
  }
  return hours * 60 + minutes;
}

/**
 * Map a JavaScript day index (0 = Sunday) onto the canonical weekday key.
 *
 * @param dayIndex - value from Date.prototype.getDay()
 * @returns the matching weekday key
 */
function weekdayFromIndex(dayIndex: number): Weekday {
  const mapping: Weekday[] = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
  const index = ((dayIndex % 7) + 7) % 7;
  return mapping[index];
}

/**
 * Format a Date as an ISO "YYYY-MM-DD" calendar date using local time.
 *
 * @param value - the date to format
 * @returns the ISO calendar date string
 */
function formatIsoDate(value: Date): string {
  const year = value.getFullYear();
  const month = value.getMonth() + 1;
  const day = value.getDate();
  const paddedMonth = month < 10 ? '0' + String(month) : String(month);
  const paddedDay = day < 10 ? '0' + String(day) : String(day);
  return String(year) + '-' + paddedMonth + '-' + paddedDay;
}

/**
 * Determine whether a given ISO date string appears in the closure list.
 *
 * @param holidays - the holiday-closure entries to inspect
 * @param isoDate - the ISO "YYYY-MM-DD" date to look for
 * @returns true when the date is a holiday closure
 */
function isHolidayClosure(holidays: HolidayClosure[], isoDate: string): boolean {
  if (!Array.isArray(holidays)) {
    return false;
  }
  for (let i = 0; i < holidays.length; i += 1) {
    const entry = holidays[i];
    if (entry !== null && entry !== undefined && entry.date === isoDate) {
      return true;
    }
  }
  return false;
}

/**
 * Find the hours entry for a specific weekday in the shared hours table.
 *
 * @param hours - the shared opening-hours table
 * @param day - the weekday key to look up
 * @returns the matching day entry, or null when the day is absent
 */
function findDay(hours: OpeningHoursTable, day: Weekday): DayHours | null {
  if (!Array.isArray(hours)) {
    return null;
  }
  for (let i = 0; i < hours.length; i += 1) {
    const entry = hours[i];
    if (entry !== null && entry !== undefined && entry.day === day) {
      return entry;
    }
  }
  return null;
}

/**
 * Test whether a minute-of-day value sits inside any opening span.
 * Span start is inclusive; span end is exclusive. Spans that close after
 * midnight (closes <= opens) wrap into the following day.
 *
 * @param spans - the day's opening spans
 * @param minuteOfDay - minutes past midnight of the instant being tested
 * @param rolloverMinutes - minutes past midnight carried from the previous day
 * @returns true when the instant falls inside an opening span
 */
function spansAreOpen(spans: OpeningSpan[], minuteOfDay: number, rolloverMinutes: number): boolean {
  if (!Array.isArray(spans)) {
    return false;
  }
  for (let i = 0; i < spans.length; i += 1) {
    const span = spans[i];
    if (span === null || span === undefined) {
      continue;
    }
    const openMinutes = clockToMinutes(span.opens);
    const closeMinutes = clockToMinutes(span.closes);
    if (openMinutes < 0 || closeMinutes < 0) {
      continue;
    }
    if (closeMinutes > openMinutes) {
      if (minuteOfDay >= openMinutes && minuteOfDay < closeMinutes) {
        return true;
      }
    } else if (closeMinutes < openMinutes) {
      if (minuteOfDay >= openMinutes) {
        return true;
      }
      if (rolloverMinutes >= 0 && rolloverMinutes < closeMinutes) {
        return true;
      }
    } else {
      if (minuteOfDay >= openMinutes) {
        return true;
      }
      if (rolloverMinutes >= 0) {
        return true;
      }
    }
  }
  return false;
}

/**
 * Compute the previous weekday key for a given weekday.
 *
 * @param day - the weekday whose predecessor is needed
 * @returns the preceding weekday key
 */
function previousWeekday(day: Weekday): Weekday {
  const index = WEEKDAYS.indexOf(day);
  if (index <= 0) {
    return 'sunday';
  }
  return WEEKDAYS[index - 1];
}

/**
 * Single source of truth for the Open/Closed badge: computes today's opening
 * status from the shared hours table, the holiday-closure list, and the
 * supplied current time.
 *
 * // req-2
 * // req-3
 *
 * @param hours - the shared opening-hours table
 * @param holidays - the holiday-closure entries that override normal hours
 * @param now - the current instant, injected so tests can freeze the clock
 * @returns the computed opening status with a display label
 */
function getOpeningStatus(hours: OpeningHoursTable, holidays: HolidayClosure[], now: Date): OpeningStatus {
  const instant = now instanceof Date ? now : new Date(NaN);
  const day = weekdayFromIndex(instant.getDay());
  const minuteOfDay = instant.getHours() * 60 + instant.getMinutes();
  const isoDate = formatIsoDate(instant);
  const entry = findDay(hours, day);
  const spans: OpeningSpan[] = entry !== null && Array.isArray(entry.spans) ? entry.spans : [];

  if (Number.isNaN(instant.getTime()) || isHolidayClosure(holidays, isoDate)) {
    return { open: false, label: 'Closed', day: day, spans: spans };
  }

  const previous = previousWeekday(day);
  const previousEntry = findDay(hours, previous);
  const previousSpans: OpeningSpan[] = previousEntry !== null && Array.isArray(previousEntry.spans) ? previousEntry.spans : [];

  let open = spansAreOpen(spans, minuteOfDay, -1);
  if (!open) {
    open = spansAreOpen(previousSpans, -1, minuteOfDay);
  }

  return { open: open, label: open ? 'Open' : 'Closed', day: day, spans: spans };
}

/**
 * Project the shared opening-hours table into the ordered seven-row shape the
 * weekly Hours & Location table renders.
 *
 * // req-10
 *
 * @param hours - the shared opening-hours table
 * @returns one row per weekday in Monday-to-Sunday order
 */
function getOpeningHoursTable(hours: OpeningHoursTable): WeeklyHoursRow[] {
  const rows: WeeklyHoursRow[] = [];
  for (let i = 0; i < WEEKDAYS.length; i += 1) {
    const day = WEEKDAYS[i];
    const entry = findDay(hours, day);
    const spans: OpeningSpan[] = entry !== null && Array.isArray(entry.spans) ? entry.spans : [];
    rows.push({ day: day, label: DAY_LABELS[day], spans: spans, closed: spans.length === 0 });
  }
  return rows;
}

/**
 * Boolean convenience wrapper over the single source-of-truth opening status.
 *
 * // req-2
 * // req-3
 *
 * @param hours - the shared opening-hours table
 * @param holidays - the holiday-closure entries that override normal hours
 * @param now - the current instant, injected so tests can freeze the clock
 * @returns true when the bakery is open at the supplied instant
 */
function isOpenNow(hours: OpeningHoursTable, holidays: HolidayClosure[], now: Date): boolean {
  return getOpeningStatus(hours, holidays, now).open;
}

/**
 * Select the products flagged as today's fresh bakes for the Home hero.
 *
 * // req-2
 *
 * @param products - the static product list
 * @param now - the current instant, injected so tests can freeze the clock
 * @returns the fresh-bake products in their original order
 */
function getTodaysFreshBakes(products: Product[], now: Date): Product[] {
  const selected: Product[] = [];
  if (!Array.isArray(products)) {
    return selected;
  }
  const instant = now instanceof Date ? now : new Date(NaN);
  const daySeed = Number.isNaN(instant.getTime()) ? 0 : instant.getDate();
  for (let i = 0; i < products.length; i += 1) {
    const product = products[i];
    if (product === null || product === undefined) {
      continue;
    }
    if (product.freshBake === true) {
      selected.push(product);
    }
  }
  if (selected.length > 0) {
    return selected;
  }
  const fallback: Product[] = [];
  for (let i = 0; i < products.length; i += 1) {
    const product = products[i];
    if (product !== null && product !== undefined && (i + daySeed) % 3 === 0) {
      fallback.push(product);
    }
  }
  return fallback;
}

/**
 * Apply the AND combination of category, dietary tag, and free-text query over
 * a single product list. An unmatched combination yields an empty array so the
 * Menu page can render its friendly empty state.
 *
 * // req-5
 *
 * @param products - the static product list
 * @param filters - the category, dietary tag, and free-text query to apply
 * @returns only the products satisfying every supplied filter
 */
function filterMenu(products: Product[], filters: MenuFilters): Product[] {
  const results: Product[] = [];
  if (!Array.isArray(products)) {
    return results;
  }
  const active = filters !== null && filters !== undefined ? filters : {};
  const category = typeof active.category === 'string' ? active.category : '';
  const tag = typeof active.tag === 'string' ? active.tag : '';
  const rawQuery = typeof active.query === 'string' ? active.query : '';
  const query = rawQuery.trim().toLowerCase();

  for (let i = 0; i < products.length; i += 1) {
    const product = products[i];
    if (product === null || product === undefined) {
      continue;
    }
    if (category !== '' && product.category !== category) {
      continue;
    }
    if (tag !== '' && (!Array.isArray(product.tags) || product.tags.indexOf(tag as DietaryTag) === -1)) {
      continue;
    }
    if (query !== '') {
      const haystack = (product.name + ' ' + product.description).toLowerCase();
      if (haystack.indexOf(query) === -1) {
        continue;
      }
    }
    results.push(product);
  }
  return results;
}

/**
 * Group a product list into the four fixed menu categories, preserving the
 * incoming order inside each bucket and always emitting all four keys.
 *
 * // req-4
 *
 * @param products - the products to group
 * @returns every category mapped to its matching products
 */
function groupByCategory(products: Product[]): Record<Category, Product[]> {
  const grouped: Record<Category, Product[]> = {
    Breads: [],
    Pastries: [],
    Cakes: [],
    Drinks: []
  };
  if (!Array.isArray(products)) {
    return grouped;
  }
  for (let i = 0; i < products.length; i += 1) {
    const product = products[i];
    if (product === null || product === undefined) {
      continue;
    }
    for (let c = 0; c < CATEGORY_ORDER.length; c += 1) {
      const category = CATEGORY_ORDER[c];
      if (product.category === category) {
        grouped[category].push(product);
      }
    }
  }
  return grouped;
}

/**
 * Render an amount as GBP with exactly two decimals.
 *
 * // req-6
 *
 * @param amount - the price in pounds
 * @returns the formatted GBP string, e.g. "£3.50"
 */
function formatGBP(amount: number): string {
  const safe = typeof amount === 'number' && Number.isFinite(amount) ? amount : 0;
  const rounded = Math.round(safe * 100) / 100;
  const sign = rounded < 0 ? '-' : '';
  const absolute = Math.abs(rounded);
  const whole = Math.floor(absolute);
  const pence = Math.round((absolute - whole) * 100);
  const boundedPence = pence === 100 ? 0 : pence;
  const boundedWhole = pence === 100 ? whole + 1 : whole;
  const penceText = boundedPence < 10 ? '0' + String(boundedPence) : String(boundedPence);
  return sign + '£' + String(boundedWhole) + '.' + penceText;
}

/**
 * Multiply a unit price by a quantity, rounded to two decimal places.
 *
 * // req-6
 *
 * @param price - the unit price in pounds
 * @param quantity - the number of items
 * @returns the line total in pounds, rounded to pence
 */
function computeLineTotal(price: number, quantity: number): number {
  const safePrice = typeof price === 'number' && Number.isFinite(price) ? price : 0;
  const safeQuantity = typeof quantity === 'number' && Number.isFinite(quantity) ? quantity : 0;
  return Math.round(safePrice * safeQuantity * 100) / 100;
}
export { getOpeningStatus, getOpeningHoursTable, isOpenNow, getTodaysFreshBakes, filterMenu, groupByCategory, formatGBP, computeLineTotal };

import { getOpeningStatus, getOpeningHoursTable, isOpenNow, getTodaysFreshBakes, filterMenu, groupByCategory, formatGBP, computeLineTotal } from "./get-opening-status.ts";
type AllergenTag = 'gluten' | 'dairy' | 'nuts' | 'egg' | 'vegan';

type MenuCategory = 'Breads' | 'Pastries' | 'Cakes' | 'Drinks';

