  mapImageUrl: string;
  mapAlt: string;
  directionsUrl: string;
  address: string;
};

type OrderFormPageProps = {
  now: Date;
  products: Product[];
  submission: OrderSubmission;
  result: ValidationResult | null;
};

type JSXElement = {
  type: string;
  props: Record<string, unknown>;
  children: JSXElement[];
};

const MAX_NAME_LENGTH: number = 200;
const MAX_EMAIL_LENGTH: number = 254;
const MAX_NOTES_LENGTH: number = 2000;
const REQUIRED_KEYS: string[] = ['name', 'pickupDate', 'product', 'quantity'];

const FIELD_DESCRIBED_BY: Record<string, string> = {
  name: 'name-error',
  phone: 'phone-error',
  email: 'email-error',
  contact: 'contact-error',
  pickupDate: 'pickupDate-error',
  product: 'product-error',
  quantity: 'quantity-error',
  notes: 'notes-error'
};

/**
 * Build a structured field-level error for a form input.
 *
 * // req-9
 *
 * @param field - The input name the error belongs to.
 * @param message - A human-readable, field-level message.
 * @returns A FieldError with an aria-describedby id and aria-invalid flag.
 */
function renderFieldError(field: string, message: string): FieldError {
  const describedById: string = FIELD_DESCRIBED_BY[field] ?? field + '-error';
  return { field: field, message: message, describedById: describedById, ariaInvalid: true };
}

/**
 * Parse a date string into a timestamp, returning null when unparseable.
 *
 * @param value - Raw pickup-date string.
 * @returns Epoch milliseconds or null.
 */
function parseTimestamp(value: string): number | null {
  if (typeof value !== 'string' || value.trim() === '') {
    return null;
  }
  const ms: number = Date.parse(value.trim());
  if (Number.isNaN(ms)) {
    return null;
  }
  return ms;
}

/**
 * Coerce a quantity input into an integer, or null when invalid.
 *
 * @param value - Raw quantity value.
 * @returns Integer quantity or null.
 */
function parseQuantity(value: string | number): number | null {
  if (typeof value === 'number') {
    if (!Number.isFinite(value) || !Number.isInteger(value)) {
      return null;
    }
    return value;
  }
  if (typeof value !== 'string' || value.trim() === '') {
    return null;
  }
  const trimmed: string = value.trim();
  if (!/^-?\d+$/.test(trimmed)) {
    return null;
  }
  const parsed: number = Number(trimmed);
  if (!Number.isFinite(parsed) || !Number.isInteger(parsed)) {
    return null;
  }
  return parsed;
}

/**
 * Validate an order enquiry against all business rules, collecting
 * field-level errors and an announcement for the live region.
 *
 * // req-8
 * // req-9
 *
 * @param order - The raw submitted order fields.
 * @param now - The injected current time used to enforce the 48-hour rule.
 * @returns A ValidationResult describing validity, errors, and preserved values.
 */
function validateOrderForm(order: OrderSubmission, now: Date): ValidationResult {
  const values: OrderSubmission = {
    name: typeof order.name === 'string' ? order.name : '',
    phone: typeof order.phone === 'string' ? order.phone : '',
    email: typeof order.email === 'string' ? order.email : '',
    pickupDate: typeof order.pickupDate === 'string' ? order.pickupDate : '',
    product: typeof order.product === 'string' ? order.product : '',
    quantity: typeof order.quantity === 'number' || typeof order.quantity === 'string' ? order.quantity : '',
    notes: typeof order.notes === 'string' ? order.notes : ''
  };

  const errors: FieldError[] = [];

  const trimmedName: string = values.name.trim();
  if (trimmedName === '') {
    errors.push(renderFieldError('name', 'Please enter your name.'));
  } else if (trimmedName.length > MAX_NAME_LENGTH) {
    errors.push(renderFieldError('name', 'Name is too long (maximum ' + MAX_NAME_LENGTH + ' characters).'));
  }

  const trimmedPhone: string = values.phone.trim();
  const trimmedEmail: string = values.email.trim();
  if (trimmedPhone === '' && trimmedEmail === '') {
    errors.push(renderFieldError('contact', 'Please provide either a phone number or an email address.'));
  }
  if (trimmedEmail.length > MAX_EMAIL_LENGTH) {
    errors.push(renderFieldError('email', 'Email is too long (maximum ' + MAX_EMAIL_LENGTH + ' characters).'));
  }

  const pickupMs: number | null = parseTimestamp(values.pickupDate);
  if (pickupMs === null) {
    errors.push(renderFieldError('pickupDate', 'Please enter a valid pickup date and time.'));
  } else if (pickupMs < now.getTime() + 48 * 60 * 60 * 1000) {
    errors.push(renderFieldError('pickupDate', 'Pickup must be at least 48 hours from now.'));
  }

  const trimmedProduct: string = values.product.trim();
  if (trimmedProduct === '') {
    errors.push(renderFieldError('product', 'Please choose a product.'));
  }

  const quantity: number | null = parseQuantity(values.quantity);
  if (quantity === null || quantity < 1) {
    errors.push(renderFieldError('quantity', 'Quantity must be a whole number of at least 1.'));
  }

  const trimmedNotes: string = values.notes.trim();
  if (trimmedNotes.length > MAX_NOTES_LENGTH) {
    errors.push(renderFieldError('notes', 'Notes are too long (maximum ' + MAX_NOTES_LENGTH + ' characters).'));
  }

  const liveRegionMessage: string =
    errors.length === 0
      ? 'No errors. Your enquiry is ready to submit.'
      : errors.length + ' ' + (errors.length === 1 ? 'error' : 'errors') + ' found: ' + errors.map(function (e: FieldError): string { return e.message; }).join(' ');

  return { valid: errors.length === 0, errors: errors, values: values, liveRegionMessage: liveRegionMessage };
}

/**
 * Produce a deterministic, human-readable order reference.
 *
 * // req-7
 *
 * @param now - Injected current time supplying the four-digit year.
 * @param sequence - Monotonic sequence number for the order window.
 * @returns A reference matching GC-<4-digit-year>-<4-digit-sequence>.
 */
function generateOrderReference(now: Date, sequence: number): string {
  const year: number = now.getFullYear();
  const yearPart: string = String(year % 10000).padStart(4, '0');
  const safeSequence: number = Number.isFinite(sequence) && Math.floor(sequence) >= 1 ? Math.floor(sequence) : 1;
  const sequencePart: string = String(safeSequence).padStart(4, '0');
  return 'GC-' + yearPart + '-' + sequencePart;
}

/**
 * Validate and confirm an order enquiry, returning a confirmation
 * carrying the reference and an echo of every submitted field.
 *
 * // req-7
 *
 * @param order - The raw submitted order fields.
 * @param now - Injected current time used for validation and the reference.
 * @returns An OrderConfirmation for a valid order; on failure a form-level
 *          message is returned that preserves the entered data.
 */
function submitOrder(order: OrderSubmission, now: Date): OrderConfirmation {
  const result: ValidationResult = validateOrderForm(order, now);
  if (!result.valid) {
    return {
      reference: '',
      values: result.values,
      lineTotal: '',
      message: 'There is a problem with your enquiry: ' + result.liveRegionMessage + ' Your entered details have been kept.'
    };
  }

  const reference: string = generateOrderReference(now, 1);
  const quantity: number = parseQuantity(result.values.quantity) ?? 1;
  const pricePence: number = 200;
  const lineTotal: string = formatGBP(pricePence * quantity);

  return {
    reference: reference,
    values: result.values,
    lineTotal: lineTotal,
    message: 'Thank you, ' + result.values.name.trim() + '. Your order ' + reference + ' is confirmed.'
  };
}

