 * or a friendly empty state.
 *
 * // req-5
 * // req-6
 *
 * @param props - Menu page inputs including the active filters.
 * @returns A JSX element tree.
 */
function renderMenuPage(props: MenuPageProps): JSX.Element {
  const filtered: Product[] = filterMenu(props.products, props.category, props.tag, props.query);
  const grouped: Record<string, Product[]> = groupByCategory(filtered);
  const categoryNames: string[] = ['Breads', 'Pastries', 'Cakes', 'Drinks'];
  const sections: JSXElement[] = [];

  if (filtered.length === 0) {
    sections.push({ type: 'p', props: { className: 'empty-state' }, children: [{ type: 'text', props: { value: props.emptyMessage }, children: [] }] });
  } else {
    for (const name of categoryNames) {
      const list: Product[] = grouped[name] ?? [];
      if (list.length === 0) {
        continue;
      }
      sections.push({
        type: 'section',
        props: { key: name },
        children: [
          { type: 'h2', props: {}, children: [{ type: 'text', props: { value: name }, children: [] }] },
          { type: 'ul', props: {}, children: list.map(function (p: Product): JSXElement {
            return { type: 'li', props: { key: p.id }, children: [
              { type: 'h3', props: {}, children: [{ type: 'text', props: { value: p.name }, children: [] }] },
              { type: 'p', props: {}, children: [{ type: 'text', props: { value: p.description }, children: [] }] },
              { type: 'p', props: {}, children: [{ type: 'text', props: { value: formatGBP(p.pricePence) }, children: [] }] },
              { type: 'p', props: {}, children: [{ type: 'text', props: { value: p.tags.join(', ') }, children: [] }] }
            ] };
          }) }
        ]
      });
    }
  }

  return {
    type: 'main',
    props: { className: 'menu' },
    children: [
      { type: 'h1', props: {}, children: [{ type: 'text', props: { value: 'Menu' }, children: [] }] }
